package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.math.BigDecimal;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Business policy and message scheduling are separate from platform capability and warehouse return rules. */
@Service public class RefundFlowAutomation {
 @Resource RefundService refunds;
 @Resource RefundWorkspace workspace;
 @Resource RefundPlatformExecution execution;
 @Resource OrderCatalog catalog;
 @Resource RefundAutomaticDecision decisions;
 @Resource RefundAutoReturns automaticReturns;
 private OrderRepository r(){return refunds.repository;}
 static Map<String,Object> defaults(){return m("auto_return_review",0,"return_review_limit","0.00","auto_difference",0,"small_refund_enabled",0,"small_refund_limit","0.00","auto_shipped_cancel",0,"auto_finish_return",0,"auto_full_cancel",0,"auto_agree_return",0,"auto_review",0,"auto_pay",0,"auto_cancel_feedback",0,"auto_intercept",0,"funds_owner","PLATFORM","payment_limit","0.00","seller_address_id","");}
 public Map<String,Object> policy(String c,long channel){List<Map<String,Object>> rows=r().db().query("SELECT enabled,policy_json,revision FROM oms_refund_flow_policy WHERE company_code=? AND channel_id=?",ROW,c,channel);Map<String,Object> p=defaults();if(!rows.isEmpty())p.putAll(obj(rows.get(0).get("policy_json")));p.put("channel_id",channel);p.put("enabled",rows.isEmpty()?0:rows.get(0).get("enabled"));p.put("revision",rows.isEmpty()?0:rows.get(0).get("revision"));List<Map<String,Object>> api=r().db().query("SELECT enabled,work_version,cursor_time,last_success,last_error FROM oms_refund_api_cursor WHERE company_code=? AND channel_id=?",ROW,c,channel);Map<String,Object> apiState=api.isEmpty()?m("enabled",0):api.get(0);apiState.put("detail_counts",r().db().query("SELECT state,COUNT(*) quantity FROM oms_refund_api_item WHERE company_code=? AND channel_id=? AND state<>'DONE' GROUP BY state",ROW,c,channel));apiState.put("detail_errors",r().db().query("SELECT refund_id,last_error FROM oms_refund_api_item WHERE company_code=? AND channel_id=? AND state='FAILED' ORDER BY id DESC LIMIT 5",ROW,c,channel));p.put("api_sync",apiState);return p;}
 public void save(String c,long channel,Map<String,Object> body,String actor){catalog.validateShop(c,channel);Map<String,Object> p=defaults();for(String key:Arrays.asList("auto_return_review","auto_difference","small_refund_enabled","auto_shipped_cancel","auto_finish_return","auto_full_cancel","auto_agree_return","auto_review","auto_pay","auto_cancel_feedback","auto_intercept")){long flag=number(body,key);require(flag==0||flag==1,"自动流程开关无效");p.put(key,flag);}BigDecimal returnLimit=money(body.getOrDefault("return_review_limit","0.00"));require(number(p,"auto_return_review")==0||returnLimit.signum()>0,"退货退款自动审核须设置正数金额上限");p.put("return_review_limit",returnLimit.toPlainString());BigDecimal small=money(body.getOrDefault("small_refund_limit","0.00"));require(number(p,"small_refund_enabled")==0||small.signum()>0,"小额免退货须设置正数的子单累计上限");p.put("small_refund_limit",small.toPlainString());String owner=text(body,"funds_owner");require(Arrays.asList("PLATFORM","OMS").contains(owner),"请明确自动付款执行方");p.put("funds_owner",owner);BigDecimal limit=money(body.getOrDefault("payment_limit","0.00"));p.put("payment_limit",limit.toPlainString());String address=text(body,"seller_address_id");require(address.isEmpty()||address.matches("[1-9][0-9]{0,18}"),"平台退货地址编号无效");p.put("seller_address_id",address);long enabled=number(body,"enabled"),api=number(body,"api_sync_enabled");require((enabled==0||enabled==1)&&(api==0||api==1),"流程或同步开关无效");require(number(p,"auto_pay")==0||("OMS".equals(owner)&&limit.signum()>0&&number(p,"auto_review")==1),"自动付款须明确由OMS执行、启用退款审核并设置正数金额上限");require(number(p,"auto_agree_return")==0||!address.isEmpty(),"自动同意退货须指定本店铺平台退货地址");
  refunds.tx().execute(tx->{List<Map<String,Object>> old=r().db().query("SELECT revision FROM oms_refund_flow_policy WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,c,channel);require(number(body,"revision")== (old.isEmpty()?0:number(old.get(0),"revision")),"自动规则已变化，请刷新");r().db().update("INSERT INTO oms_refund_flow_policy(company_code,channel_id,enabled,policy_json,updated_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),policy_json=VALUES(policy_json),updated_by=VALUES(updated_by),revision=revision+1",c,channel,enabled,encode(p),actor);if(body.containsKey("api_sync_enabled"))r().db().update("INSERT INTO oms_refund_api_cursor(company_code,channel_id,enabled) VALUES (?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),work_version=work_version+1,next_run=NOW()",c,channel,api);for(Long id:r().db().queryForList("SELECT id FROM oms_refund WHERE company_code=? AND channel_id=? AND state NOT IN ('COMPLETED','CLOSED','CANCELED') ORDER BY id DESC LIMIT 100",Long.class,c,channel))changed(r(),c,id);return null;});
 }
 /** Intake has its own optimistic version; saving automation never overwrites it. */
 public void saveApiSync(String c,long channel,Map<String,Object> body){catalog.validateShop(c,channel);long enabled=number(body,"enabled"),version=number(body,"work_version");require(enabled==0||enabled==1,"接口同步开关无效");int updated=version==0?r().db().update("INSERT IGNORE INTO oms_refund_api_cursor(company_code,channel_id,enabled) VALUES (?,?,?)",c,channel,enabled):r().db().update("UPDATE oms_refund_api_cursor SET enabled=?,work_version=work_version+1,next_run=NOW() WHERE company_code=? AND channel_id=? AND work_version=?",enabled,c,channel,version);require(updated==1,"接口同步配置或进度已变化，请刷新后保存");}
 static void changed(OrderRepository r,String c,long id){if(r.messaging()==null)return;r.db().update("INSERT INTO oms_refund_flow_task(company_code,refund_id) SELECT b.company_code,b.id FROM oms_refund b JOIN oms_refund_flow_policy p ON p.company_code=b.company_code AND p.channel_id=b.channel_id AND p.enabled=1 WHERE b.company_code=? AND b.id=? ON DUPLICATE KEY UPDATE state='PENDING',work_version=work_version+1,next_attempt=NOW()",c,id);List<Long> versions=r.db().queryForList("SELECT work_version FROM oms_refund_flow_task WHERE company_code=? AND refund_id=?",Long.class,c,id);if(!versions.isEmpty()){long version=versions.get(0);if(r.db().queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code=? AND service_code='order' AND message_type='REFUND_FLOW' AND business_id=? AND business_version=?",Long.class,c,String.valueOf(id),version)==0)r.messaging().enqueue(c,"REFUND_FLOW",id,version,"REFFLOW"+id,id+":"+version,0);}}
 public void retry(String c,long id){refunds.business(c,id,false);refunds.tx().execute(tx->{changed(r(),c,id);return null;});}
 public void scan(String c){if(r().messaging()==null)return;refunds.tx().execute(tx->{for(Map<String,Object> task:r().db().query("SELECT t.refund_id,t.work_version FROM oms_refund_flow_task t WHERE t.company_code=? AND t.state IN ('PENDING','WAITING','MANUAL') AND t.next_attempt<=NOW() AND NOT EXISTS(SELECT 1 FROM oms_message_outbox o WHERE o.company_code=t.company_code AND o.service_code='order' AND o.message_type='REFUND_FLOW' AND o.business_id=CAST(t.refund_id AS CHAR) AND o.business_version=t.work_version AND o.process_state IN ('PENDING','WAITING','PROCESSING')) ORDER BY t.next_attempt,t.refund_id LIMIT 20 FOR UPDATE",ROW,c)){long id=number(task,"refund_id"),version=number(task,"work_version")+1;r().db().update("UPDATE oms_refund_flow_task SET work_version=?,next_attempt=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND refund_id=?",version,c,id);r().messaging().enqueue(c,"REFUND_FLOW",id,version,"REFFLOW"+id,id+":"+version,0);}return null;});}
 private Map<String,Object> result(String c,long id,long version,String state,String message){r().db().update("UPDATE oms_refund_flow_task SET state=?,last_message=?,next_attempt=DATE_ADD(NOW(),INTERVAL ? SECOND) WHERE company_code=? AND refund_id=? AND work_version=?",state,message.substring(0,Math.min(500,message.length())),"MANUAL".equals(state)?300:30,c,id,version);return m("state",state,"message",message);}
 private boolean operation(String c,long id,String action,String hash){return r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_operation WHERE company_code=? AND refund_id=? AND action=? AND (approved_hash=? OR approved_hash IS NULL) AND state IN ('PENDING','RUNNING','UNKNOWN','ACCEPTED','SUCCESS')",Long.class,c,id,action,hash)>0;}
 private Map<String,Object> submit(String c,Map<String,Object> b,String action,Map<String,Object> arguments,Map<String,Object> rules){List<Map<String,Object>> prior=r().db().query("SELECT state,result_message FROM oms_refund_operation WHERE company_code=? AND refund_id=? AND action=? AND approved_hash=? AND source_version=? AND policy_revision=? ORDER BY id DESC LIMIT 1",ROW,c,b.get("id"),action,b.get("approved_hash"),b.get("approved_version"),rules.get("revision"));require(prior.isEmpty()||!"FAILED".equals(text(prior.get(0),"state")),"本规则的原平台动作已明确失败，请人工核对原记录，或修正规则后重新执行；不会定时重复提交");Map<String,Object> submitted=execution.submit(c,number(b,"id"),action,m("control_version",b.get("control_version"),"auto_policy_revision",rules.get("revision"),"confirmed",true,"reason","店铺自动流程：已采用审核方案；动作 "+action,"arguments",arguments),"自动售后流程");Map<String,Object> result=r().db().queryForMap("SELECT state,result_message FROM oms_refund_operation WHERE company_code=? AND id=?",c,submitted.get("id"));require(!"FAILED".equals(text(result,"state")),text(result,"result_message")+"；请人工核对原平台动作后继续");return submitted;}
 public Map<String,Object> step(String c,long id,long version){Map<String,Object> b=refunds.business(c,id,false),p=refunds.platform(c,number(b,"platform_refund_id"),false),rules=policy(c,number(b,"channel_id"));List<Long> current=r().db().queryForList("SELECT work_version FROM oms_refund_flow_task WHERE company_code=? AND refund_id=?",Long.class,c,id);if(current.isEmpty()||current.get(0)!=version)return m("state","DONE","message","已有新流程通知，结束原通知");if(number(rules,"enabled")!=1)return result(c,id,version,"DONE","本店铺已关闭自动流程，保留已执行结果");r().db().update("UPDATE oms_refund_flow_task SET policy_revision=? WHERE company_code=? AND refund_id=? AND work_version=?",rules.get("revision"),c,id,version);
  try{if(!"VALID".equals(text(p,"source_state")))return result(c,id,version,"MANUAL","平台来源资料异常，请先核对来源");if("CLOSED".equals(text(p,"platform_status")))return result(c,id,version,"MANUAL","平台申请关闭，请核对原货物动作；不会自动恢复已撤回发货");if("SUCCESS".equals(text(b,"funds_state"))&&"DONE".equals(text(b,"goods_state"))&&"APPROVED".equals(text(b,"review_state")))return result(c,id,version,"DONE","平台资金与货物处理均已完成");
    if(!"APPROVED".equals(text(b,"review_state"))){if(decisions!=null&&(number(rules,"small_refund_enabled")==1||number(rules,"auto_shipped_cancel")==1||number(rules,"auto_return_review")==1||number(rules,"auto_difference")==1)&&decisions.decide(c,id,rules))return result(c,id,version,"WAITING","已按商家明确授权自动确认退款用途及货物范围");if(number(rules,"auto_full_cancel")==1&&autoCancel(c,b,p,rules))return result(c,id,version,"WAITING","已按商家全额未发取消规则确认原商品范围，后台分项截单");return result(c,id,version,"MANUAL","请确认退款用途与货物范围；不以少量退款或原因关键词判断差价");}
    if(number(b,"approved_version")!=number(p,"version"))return result(c,id,version,"MANUAL","已审核申请内容已变化，请核对原执行记录后重审");String hash=text(b,"approved_hash");
    if(automaticReturns!=null&&!"KEEP".equals(text(b,"goods_action"))&&!"DONE".equals(text(b,"goods_state"))){automaticReturns.advance(c,id,rules);b=refunds.business(c,id,false);}
    if(number(rules,"auto_agree_return")==1&&"REFUND_AND_RETURN".equals(text(p,"dispute_type"))&&"WAIT_SELLER_AGREE".equals(text(p,"platform_status"))&&!operation(c,id,"AGREE_RETURN",hash)){submit(c,b,"AGREE_RETURN",m("seller_address_id",rules.get("seller_address_id")),rules);return result(c,id,version,"WAITING","已提交平台同意退货，等待平台状态确认");}
    if(number(rules,"auto_intercept")==1&&Arrays.asList("INTERCEPT","MIXED").contains(text(b,"goods_action"))&&!operation(c,id,"INTERCEPT",hash)){long plans=r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND return_mode='INTERCEPT'",Long.class,c,id);if(plans>0){submit(c,b,"INTERCEPT",m(),rules);return result(c,id,version,"WAITING","已申请在途拦截，等待真实物流处理结果");}}
    if(number(rules,"auto_cancel_feedback")==1&&"DONE".equals(text(b,"goods_state"))&&!operation(c,id,"CANCEL_FEEDBACK",hash)&&"CANCELED".equals(text(RefundFulfillment.context(r(),c,b),"stage"))){submit(c,b,"CANCEL_FEEDBACK",m(),rules);return result(c,id,version,"WAITING","已回告平台取消发货结果，等待平台后续处理");}
    if(!"KEEP".equals(text(b,"goods_action"))&&!"DONE".equals(text(b,"goods_state")))return result(c,id,version,"WAITING","等待本退款取消、退回、实收及货物结案；合包不合并各退款资金");
    if("SUCCESS".equals(text(b,"funds_state")))return result(c,id,version,"DONE","平台已退款，不再提交付款");
    if(number(rules,"auto_review")==1&&!operation(c,id,"REVIEW",hash)){submit(c,b,"REVIEW",m(),rules);return result(c,id,version,"WAITING","已提交平台退款审核，审核成功不等于已经付款");}
    if(number(rules,"auto_pay")==1&&"OMS".equals(text(rules,"funds_owner"))&&!operation(c,id,"PAY",hash)){if(money(b.get("refund_fee")).compareTo(money(rules.get("payment_limit")))>0)return result(c,id,version,"MANUAL","本次退款超过店铺自动付款上限，请人工核对");Map<String,Object> capability=data(execution.channel.capability(c,number(b,"channel_id"),com.ruoyi.common.core.constant.SecurityConstants.INNER));if(number(capability,"ignore_code")!=1)return result(c,id,version,"MANUAL","自动付款需要商家明确开通免验证码；当前请人工输入验证码付款");b=refunds.business(c,id,false);submit(c,b,"PAY",m(),rules);return result(c,id,version,"WAITING","已提交本退款付款，等待平台最终资金结果");}
    return result(c,id,version,"WAITING","等待平台处理结果；资金执行方为 "+("OMS".equals(text(rules,"funds_owner"))?"OMS":"平台"));
  }catch(IllegalArgumentException invalid){return result(c,id,version,"MANUAL",invalid.getMessage());}catch(RuntimeException unavailable){return result(c,id,version,"WAITING","服务或平台结果暂未确认，将先核对原操作，不重复执行付款");}
 }
 private boolean autoCancel(String c,Map<String,Object> hint,Map<String,Object> source,Map<String,Object> rules){
  return refunds.tx().execute(tx->{
   refunds.lockOriginal(c,number(hint,"channel_id"),text(hint,"platform_tid"));
   Map<String,Object> liveRules=policy(c,number(hint,"channel_id"));
   if(number(liveRules,"enabled")!=1||number(liveRules,"auto_full_cancel")!=1||number(liveRules,"revision")!=number(rules,"revision"))return false;
   Map<String,Object> b=refunds.business(c,number(hint,"id"),true),p=refunds.platform(c,number(source,"id"),true);
   if(r().db().queryForObject("SELECT COUNT(*) FROM oms_platform_order WHERE company_code=? AND id=? AND change_pending=1",Long.class,c,b.get("original_platform_order_id"))>0)return false;
   return autoCancelLocked(c,b,p,liveRules);
  });
 }
 @SuppressWarnings("unchecked") private boolean autoCancelLocked(String c,Map<String,Object> b,Map<String,Object> p,Map<String,Object> rules){
  if(!"REFUND".equals(text(p,"dispute_type"))||!"WAIT_SELLER_AGREE".equals(text(p,"platform_status"))||!"PENDING".equals(text(b,"review_state"))||!text(p,"special_type").isEmpty())return false;Map<String,Object> context=RefundFulfillment.context(r(),c,b);if(!"UNSHIPPED".equals(text(context,"stage"))||Boolean.TRUE.equals(context.get("uncertain")))return false;
  Map<String,Object> doc=OrderDocumentInfo.stored(r().db().queryForObject("SELECT document_info FROM oms_order WHERE company_code=? AND id=?",String.class,c,b.get("order_id")));Object raw=doc.get("lines");BigDecimal paid=null;if(raw instanceof Collection)for(Object item:(Collection<?>)raw){Map<String,Object> line=obj(item);if(text(b,"platform_oid").equals(text(line,"platform_oid"))&&line.get("goods_payment")!=null&&text(line,"payment_source").startsWith("平台"))paid=money(line.get("goods_payment"));}if(paid==null||paid.signum()<=0)return false;
  long unknown=r().db().queryForObject("SELECT COUNT(*) FROM oms_platform_refund x LEFT JOIN oms_refund y ON y.company_code=x.company_code AND y.platform_refund_id=x.id WHERE x.company_code=? AND x.channel_id=? AND x.platform_tid=? AND x.platform_oid=? AND x.id<>? AND x.platform_status<>'CLOSED' AND (x.platform_status<>'SUCCESS' OR y.review_state<>'APPROVED' OR y.goods_action<>'KEEP' OR y.id IS NULL)",Long.class,c,b.get("channel_id"),b.get("platform_tid"),b.get("platform_oid"),p.get("id"));if(unknown>0)return false;BigDecimal previous=r().db().queryForObject("SELECT COALESCE(SUM(refund_fee),0) FROM oms_platform_refund WHERE company_code=? AND channel_id=? AND platform_tid=? AND platform_oid=? AND id<>? AND platform_status='SUCCESS'",BigDecimal.class,c,b.get("channel_id"),b.get("platform_tid"),b.get("platform_oid"),p.get("id"));if(paid.subtract(previous).compareTo(money(p.get("refund_fee")))!=0)return false;
  List<Map<String,Object>> scopes=new ArrayList<>();for(Object item:(List<?>)context.get("lines")){Map<String,Object> line=obj(item);if(number(line,"unshipped_quantity")>0)scopes.add(m("action","CANCEL","order_line_id",line.get("order_line_id"),"quantity",line.get("unshipped_quantity")));}if(scopes.isEmpty())return false;
  workspace.review(c,number(b,"id"),m("control_version",b.get("control_version"),"platform_version",p.get("version"),"purpose","CANCEL","goods_action","MIXED","goods_tasks",scopes,"reason","命中商家规则：未出库且申请剩余商品实付全额退款，按取消购买处理","evidence","店铺规则版本 "+rules.get("revision")+"；原子单商品实付 "+paid+"；前次已确认金额退款 "+previous),"自动售后规则");return true;
 }
}
